@import 'tailwindcss';
@import 'maplibre-gl/dist/maplibre-gl.css';

@theme {
  --font-sans:
    'Inter var', 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, monospace;

  /* Surfaces, from the page floor up to the highest floating card. */
  --color-void: #06070b;
  --color-surface: #0b0d13;
  --color-raised: #11141c;
  --color-hover: #171b26;
  --color-line: #1e2331;
  --color-line-soft: #161a25;

  --color-ink: #f2f4f8;
  --color-ink-dim: #a2abbd;
  --color-ink-faint: #6b7488;

  --color-accent: #5eead4;
}

@layer base {
  * {
    -webkit-tap-highlight-color: transparent;
  }

  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--color-void);
    color: var(--color-ink);
    font-family: var(--font-sans);
    font-feature-settings: 'cv02', 'cv03', 'cv04', 'ss01';
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    overscroll-behavior: none;
  }

  ::selection {
    background: color-mix(in srgb, var(--color-accent) 30%, transparent);
    color: #fff;
  }

  button {
    cursor: pointer;
    font: inherit;
    color: inherit;
  }

  input,
  select {
    font: inherit;
    color: inherit;
  }

  :focus-visible {
    outline: 2px solid color-mix(in srgb, var(--color-accent) 70%, transparent);
    outline-offset: 2px;
  }
}

@layer utilities {
  .tabular {
    font-variant-numeric: tabular-nums;
  }

  /* Thin, dark scrollbars so panels do not sprout bright chrome. */
  .scroll-slim {
    scrollbar-width: thin;
    scrollbar-color: #2a3040 transparent;
  }
  .scroll-slim::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  .scroll-slim::-webkit-scrollbar-thumb {
    background: #2a3040;
    border-radius: 99px;
    border: 2px solid transparent;
    background-clip: content-box;
  }
  .scroll-slim::-webkit-scrollbar-thumb:hover {
    background: #3a4255;
    background-clip: content-box;
  }
  .scroll-slim::-webkit-scrollbar-track {
    background: transparent;
  }
}

/* ---- MapLibre chrome, restyled to match the panels ---- */

.maplibregl-map {
  font-family: var(--font-sans);
}

.maplibregl-ctrl-group {
  background: color-mix(in srgb, var(--color-raised) 88%, transparent) !important;
  backdrop-filter: blur(12px);
  border: 1px solid var(--color-line) !important;
  border-radius: 10px !important;
  box-shadow: 0 8px 24px rgb(0 0 0 / 0.45) !important;
  overflow: hidden;
}

.maplibregl-ctrl-group button {
  width: 30px !important;
  height: 30px !important;
  background-color: transparent !important;
}

.maplibregl-ctrl-group button + button {
  border-top: 1px solid var(--color-line) !important;
}

.maplibregl-ctrl-group button:hover {
  background-color: var(--color-hover) !important;
}

.maplibregl-ctrl-group button .maplibregl-ctrl-icon {
  filter: invert(1) brightness(0.9);
}

.maplibregl-ctrl-attrib {
  background: rgb(6 7 11 / 0.78) !important;
  color: var(--color-ink-faint) !important;
  font-size: 10px !important;
  border-radius: 8px 0 0 0 !important;
  backdrop-filter: blur(8px);
}

.maplibregl-ctrl-attrib a {
  color: var(--color-ink-dim) !important;
}

.maplibregl-ctrl-attrib-button {
  background-color: rgb(255 255 255 / 0.55) !important;
}

.maplibregl-ctrl-scale {
  background: rgb(6 7 11 / 0.7) !important;
  border-color: var(--color-line) !important;
  color: var(--color-ink-dim) !important;
  font-size: 10px !important;
  font-variant-numeric: tabular-nums;
  border-radius: 0 0 4px 4px;
}

.maplibregl-canvas:focus {
  outline: none;
}

/* ---- Motion ---- */

@keyframes ping-ring {
  0% {
    transform: scale(0.4);
    opacity: 0.85;
  }
  100% {
    transform: scale(2.6);
    opacity: 0;
  }
}

@keyframes fade-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.animate-fade-rise {
  animation: fade-rise 0.24s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}

.animate-live {
  animation: pulse-dot 2s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .animate-fade-rise,
  .animate-live {
    animation: none;
  }
}

