  LAYER_IDS,
  PLATE_SOURCE,
  PULSE_SOURCE,
  QUAKE_SOURCE,
  hoverLayer,
  plateLayers,
  pulseLayer,
  quakeDotLayer,
  quakeGlowLayer,
  selectLayers,
