            />
            <span className="tabular text-sm font-semibold">
              M {fmt.magnitude(tooltip.quake.mag)}
            </span>
            <span className="tabular text-[11px] text-ink-faint">
              {fmt.depth(tooltip.quake.depth)} deep
            </span>
          </div>
