import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  Map as MapLibreMap,
  NavigationControl,
  ScaleControl,
  type GeoJSONSource,
  type MapMouseEvent,
} from 'maplibre-gl'
import type { Quake } from '../lib/usgs'
import type { ColorMode } from '../lib/color'
import { colorExpression, colorFor } from '../lib/color'
import { getBasemap, type BasemapId } from '../lib/basemaps'
import {
  LAYER_IDS,
  PLATE_SOURCE,
  PULSE_SOURCE,
  QUAKE_SOURCE,
  hoverLayer,
  plateLayers,
  pulseLayer,
  quakeDotLayer,
  quakeGlowLayer,
  selectLayers,
} from '../lib/layers'
import * as fmt from '../lib/format'

export type Projection = 'mercator' | 'globe'

interface MapViewProps {
  quakes: Quake[]
  selected: Quake | null
  hoveredId: string | null
  colorMode: ColorMode
  now: number
  basemap: BasemapId
  projection: Projection
  showPlates: boolean
  /** Bumped by the parent to request the camera fly to the selected event. */
  focusToken: number
  onSelect: (id: string | null) => void
  onHover: (id: string | null) => void
}

interface Tooltip {
  x: number
  y: number
  quake: Quake
}

type FeatureCollection = {
  type: 'FeatureCollection'
  features: Array<{
    type: 'Feature'
    properties: Record<string, unknown>
    geometry: { type: 'Point'; coordinates: [number, number] }
  }>
}

function toFeatureCollection(quakes: Quake[]): FeatureCollection {
  return {
    type: 'FeatureCollection',
    features: quakes.map((q) => ({
      type: 'Feature',
      properties: {
        id: q.id,
        mag: q.mag,
        depth: q.depth,
        time: q.time,
        alert: q.alert ?? '',
      },
      geometry: { type: 'Point', coordinates: [q.lon, q.lat] },
    })),
  }
}

const EMPTY: FeatureCollection = { type: 'FeatureCollection', features: [] }

